shape.patch:
--- a/json.mbt
+++ b/json.mbt
@@ -187,9 +187,14 @@
         guard q is Object(q) else {
           raise StnError("invalid_input", "query must be an object")
         }
-        fields(q, ["from", "to"])
-        let a = text(required(q, "from"), "from")
-        let b = text(required(q, "to"), "to")
+        let (a, b) = if q.length() == 2 &&
+          q.get("from") is Some(from) &&
+          q.get("to") is Some(to) {
+          (text(from, "from"), text(to, "to"))
+        } else {
+          fields(q, ["from", "to"])
+          (text(required(q, "from"), "from"), text(required(q, "to"), "to"))
+        }
         let from = lookup_name(index, a)
         let to = lookup_name(index, b)
         queries.push((from, to))

scan.patch:
--- a/json.mbt
+++ b/json.mbt
@@ -187,9 +187,23 @@
         guard q is Object(q) else {
           raise StnError("invalid_input", "query must be an object")
         }
-        fields(q, ["from", "to"])
-        let a = text(required(q, "from"), "from")
-        let b = text(required(q, "to"), "to")
+        let mut from = None
+        let mut to = None
+        for key, value in q {
+          match key {
+            "from" => from = Some(value)
+            "to" => to = Some(value)
+            _ => raise StnError("invalid_input", "unknown field: " + key)
+          }
+        }
+        guard from is Some(from) else {
+          raise StnError("invalid_input", "missing field: from")
+        }
+        let a = text(from, "from")
+        guard to is Some(to) else {
+          raise StnError("invalid_input", "missing field: to")
+        }
+        let b = text(to, "to")
         let from = lookup_name(index, a)
         let to = lookup_name(index, b)
         queries.push((from, to))

